<script setup>
import { computed, ref, watch } from 'vue';
import { api } from '../../services/api';
import SvgIcon from '../SvgIcon.vue';
const props = defineProps({ projectId: String, state: Object, episodeId: String, episodes: Array });
const emit = defineEmits(['refresh', 'error', 'select-episode']);
const script = ref({ scenes: [] }); const busy = ref(false); const selected = ref(0); const compare = ref(false); const showHistory = ref(false); const revisions = ref([]);
const episodeState = computed(() => props.state?.episode_state || props.state);
watch(() => episodeState.value, s => { script.value = JSON.parse(JSON.stringify(s?.content?.scenes ? s.content : { scenes: [] })); selected.value = 0; }, { immediate: true });
async function generate() { if (!props.episodeId) return emit('error', '请先选择剧集'); busy.value = true; try { await api.generateStage(props.projectId, 3, props.episodeId); emit('refresh'); } catch(e) { emit('error', e.message); } finally { busy.value = false; } }
async function save() { if (!props.episodeId || !script.value.scenes.length) return; try { return await api.saveStage(props.projectId, 3, script.value, props.episodeId); } catch(e) { emit('error', e.message); throw e; } }
async function review() { busy.value = true; try { await save(); await api.reviewStage(props.projectId, 3, props.episodeId); emit('refresh'); } catch(e) { emit('error', e.message); } finally { busy.value = false; } }
async function loadHistory() { if (!episodeState.value?.id) return; revisions.value = await api.revisions(episodeState.value.id); showHistory.value = true; }
function addScene() { script.value.scenes.push({ scene_number: script.value.scenes.length + 1, location: '', time_environment: '', characters: [], action: '', dialogue: [], internal_monologue: '', narration: '', transition: '', pacing: '' }); selected.value = script.value.scenes.length - 1; }
function dialogueText(scene) { return (scene.dialogue || []).map(d => `${d.character}：${d.line}${d.emotion ? `（${d.emotion}）` : ''}`).join('\n'); }
function setDialogue(scene, value) { scene.dialogue = value.split('\n').filter(Boolean).map(line => { const [character, ...rest] = line.split(/[：:]/); return { character, line: rest.join('：') }; }); }
defineExpose({ save });
</script>
<template>
  <div>
    <div class="script-toolbar"><div class="episode-select"><span>当前剧集</span><select :value="episodeId" @change="emit('select-episode', $event.target.value)"><option v-for="e in episodes" :key="e.id" :value="e.id">第 {{ e.episode_number }} 集 · {{ e.title }}</option></select></div><div class="toolbar-actions"><button class="btn secondary small" @click="compare = !compare">原著对照</button><button class="btn secondary small" @click="loadHistory">版本记录</button><button class="btn secondary small" :disabled="busy || !script.scenes.length" @click="review">AI 质量审阅</button><button class="btn primary small" :disabled="busy || !episodeId" @click="generate"><SvgIcon name="spark" :size="15" />{{ busy ? 'AI 工作中…' : script.scenes.length ? '重新生成剧本' : '生成本集剧本' }}</button></div></div>
    <div class="script-workspace" :class="{ comparing: compare }">
      <aside v-if="compare" class="original-panel"><div class="panel-heading">原著对照</div><p>当前改编应忠于已审批 Story Bible 与剧集规划。原文请在小说分析阶段查阅，修改上游会使本阶段自动标记为需要修订。</p><div v-if="script.quality_review" class="review-box"><strong>AI 审阅 · {{ script.quality_review.score }} 分</strong><p>{{ script.quality_review.summary }}</p><div v-for="(issue, i) in script.quality_review.issues" :key="i" class="issue"><b>{{ issue.severity }}</b>{{ issue.issue }}<small>{{ issue.suggestion }}</small></div></div></aside>
      <section class="editor-panel">
        <div v-if="!script.scenes.length" class="empty-content"><SvgIcon name="edit" :size="29" /><h3>本集还没有剧本</h3><p>AI 将使用原著、Story Bible、人物设定和本集规划生成场景级剧本。</p><button class="btn primary" :disabled="busy || !episodeId" @click="generate">生成剧本</button></div>
        <template v-else><div class="scene-tabs"><button v-for="(scene, i) in script.scenes" :key="i" :class="{ active: selected === i }" @click="selected = i">场景 {{ i + 1 }}</button><button class="add-scene" @click="addScene">+ 添加</button></div><div v-if="script.scenes[selected]" class="scene-editor"><div class="form-grid"><label>场景地点<input v-model="script.scenes[selected].location" /></label><label>时间与环境<input v-model="script.scenes[selected].time_environment" /></label></div><label>角色出场<input v-model="script.scenes[selected].characters" placeholder="林枫、女子" /></label><label>动作与场面<textarea v-model="script.scenes[selected].action" class="action-input"></textarea></label><label>对白与情绪<textarea :value="dialogueText(script.scenes[selected])" @input="setDialogue(script.scenes[selected], $event.target.value)" placeholder="角色：对白（情绪）"></textarea></label><div class="form-grid"><label>内心独白<textarea v-model="script.scenes[selected].internal_monologue"></textarea></label><label>旁白<textarea v-model="script.scenes[selected].narration"></textarea></label></div><div class="form-grid"><label>转场<input v-model="script.scenes[selected].transition" /></label><label>节奏<input v-model="script.scenes[selected].pacing" /></label></div><div class="editor-actions"><span>修改保存后，相关分镜会标记为需要复核，不影响其他剧集。</span><button class="btn primary small" @click="save">保存剧本</button></div></div></template>
      </section>
    </div>
    <div v-if="showHistory" class="modal-mask" @click.self="showHistory = false"><div class="modal clean-modal"><div class="history-heading"><h2>剧本版本记录</h2><button class="icon-btn" @click="showHistory = false">×</button></div><p v-if="!revisions.length" class="muted">还没有历史版本，首次修改保存后会自动记录。</p><details v-for="r in revisions" :key="r.id"><summary>版本 {{ r.revision_number }} · {{ r.note }} · {{ new Date(r.created_at).toLocaleString() }}</summary><pre>{{ JSON.stringify(r.content, null, 2) }}</pre></details></div></div>
  </div>
</template>
<style scoped>
.script-toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px}.episode-select{display:flex;align-items:center;gap:9px;font-size:12px;color:var(--text-secondary)}.episode-select select{min-width:240px}.toolbar-actions{display:flex;gap:7px;flex-wrap:wrap}.script-workspace{display:grid;grid-template-columns:1fr;gap:14px}.script-workspace.comparing{grid-template-columns:300px 1fr}.original-panel,.editor-panel{background:var(--surface);border:1px solid var(--border);border-radius:11px;overflow:hidden}.original-panel{padding:18px;color:var(--text-secondary);font-size:13px;line-height:1.7}.panel-heading{font-weight:650;color:var(--text);border-bottom:1px solid var(--border);padding-bottom:12px}.review-box{margin-top:20px}.review-box strong{color:var(--text)}.issue{padding:10px 0;border-top:1px solid var(--border)}.issue b{display:inline-block;color:#b45309;margin-right:6px;font-size:11px}.issue small{display:block;margin-top:4px}.scene-tabs{display:flex;gap:3px;padding:10px 12px;border-bottom:1px solid var(--border);overflow:auto}.scene-tabs button{background:transparent;color:var(--text-secondary);font-size:12px;padding:8px 12px;white-space:nowrap}.scene-tabs button.active{background:var(--accent-soft);color:var(--accent)}.scene-tabs .add-scene{margin-left:auto}.scene-editor{padding:20px}.scene-editor label{display:block;font-size:12px;font-weight:600;margin:12px 0}.scene-editor input,.scene-editor textarea{width:100%;margin-top:6px}.scene-editor textarea{min-height:75px}.scene-editor .action-input{min-height:130px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.editor-actions{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid var(--border);padding-top:15px;margin-top:18px}.editor-actions span{font-size:11px;color:var(--text-secondary)}.empty-content{text-align:center;padding:110px 20px;color:var(--text-secondary)}.empty-content h3{color:var(--text)}.history-heading{display:flex;justify-content:space-between}.clean-modal details{border-top:1px solid var(--border);padding:12px 0}.clean-modal summary{cursor:pointer;font-size:13px}.clean-modal pre{max-height:300px;overflow:auto;background:var(--page);padding:12px;font-size:11px;white-space:pre-wrap}@media(max-width:900px){.script-toolbar{align-items:flex-start;flex-direction:column}.script-workspace.comparing{grid-template-columns:1fr}.original-panel{max-height:300px;overflow:auto}}@media(max-width:600px){.form-grid{grid-template-columns:1fr}.episode-select{align-items:flex-start;flex-direction:column}.episode-select select{min-width:100%;width:100%}}
</style>
